// Extract OCR text from webhook payload (handle raw, body-wrapped, and query JSON)
const payload = $input.item.json || {};
const body = payload.body || {};
const query = payload.query || {};
const ocrText = (payload.ocr_text ?? body.ocr_text ?? query.ocr_text ?? '').toString();
const maxLength = Number(payload.max_length ?? body.max_length ?? query.max_length ?? 2000);

// Truncate if too long (Gemini input limits)
const truncatedText = ocrText.length > maxLength 
  ? ocrText.substring(0, maxLength) + '...'
  : ocrText;

// Basic validation
if (!ocrText || ocrText.trim().length < 20) {
  return {
    json: {
      skip_llm: true,
      sense_rating: 20,
      reasoning: 'Insufficient text extracted (less than 20 characters)',
      detected_structure: {
        has_vendor_info: false,
        has_line_items: false,
        has_amounts: false,
        has_dates: false
      },
      confidence: 'high',
      error: 'Text too short for analysis',
      debug_payload_keys: Object.keys(payload)
    }
  };
}

return {
  json: {
    skip_llm: false,
    ocr_text: truncatedText,
    original_length: ocrText.length,
    truncated: ocrText.length > maxLength,
    debug_payload_keys: Object.keys(payload)
  }
};

