parameters.functionCode:
// Parse Gemini API response
const response = $input.item.json;

try {
  // Gemini returns: { candidates: [{ content: { parts: [{ text: "..." }] } }] }
  const candidates = response.candidates || [];

  if (candidates.length === 0) {
    throw new Error('No candidates in Gemini response');
  }

  const content = candidates[0].content;
  const parts = content.parts || [];

  if (parts.length === 0) {
    throw new Error('No parts in content');
  }

  // Extract JSON text
  const jsonText = parts[0].text;

  // Parse the JSON
  const result = JSON.parse(jsonText);

  // Validate required fields
  if (typeof result.sense_rating !== 'number' || 
      result.sense_rating < 0 || 
      result.sense_rating > 100) {
    throw new Error('Invalid sense_rating');
  }

  return {
    json: {
      sense_rating: result.sense_rating,
      reasoning: result.reasoning || 'No reasoning provided',
      detected_structure: result.detected_structure || {
        has_vendor_info: false,
        has_line_items: false,
        has_amounts: false,
        has_dates: false
      },
      confidence: result.confidence || 'medium',
      error: null
    }
  };

} catch (error) {
  // Fallback on parsing error
  return {
    json: {
      sense_rating: 50,
      reasoning: `LLM response parsing failed: ${error.message}`,
      detected_structure: {
        has_vendor_info: false,
        has_line_items: false,
        has_amounts: false,
        has_dates: false
      },
      confidence: 'low',
      error: error.message
    }
  };
}
